  let L := lay Σ in
  disjoint_from W (l_FSB L + 0x58) 9 /\ fs_cls_avoid W (l_FSB L) 0 (fs0 Σ) /\ fs_cls_avoid W (l_FSB L) 1 (fs2 Σ)
  /\ (fs_cls_avoid W (l_FSB L) 6 (fs4 Σ) /\ fs_cls_avoid W (l_FSB L) 2 (fs1 Σ) /\ fs_cls_avoid W (l_FSB L) 3 (fc3 Σ) /\ fs_cls_avoid W (l_FSB L) 4 (fc4 Σ) /\ fs_cls_avoid W (l_FSB L) 7 (fc7 Σ)) /\ dsjl W fs_lits /\ disjoint_from W (l_DTV L + 24) 8 /\ disjoint_from W (l_T L + 48) 16
